export function getRandomStatements(count: number, subject?: FoFStatement['subject']): FoFStatement[] {
  const pool = subject ? FOF_STATEMENTS.filter(s => s.subject === subject) : FOF_STATEMENTS;
  return [...pool].sort(() => Math.random() - 0.5).slice(0, count);
}
